<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Pterodactyl\Models\Egg; use Pterodactyl\Models\Node; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\OgImage; use Pterodactyl\Services\Dezerx\Settings; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Services\Dezerx\Appearance; use Pterodactyl\Services\Dezerx\Billing\Billing; class BotConfig { public const KEY = 'discord_bot'; public const GLOBAL = 'global'; public const PERSONAL = 'personal'; public const MODES = [self::GLOBAL, self::PERSONAL]; public const PERMISSIONS = 1024 | 2048 | 16384 | 32768 | 65536 | 131072 | 262144; public const DEFAULT_SLOTS = 3; public const MAX_SLOTS = 50; public static function enabled(): bool { return (bool) (Addons::get(Addons::DISCORD_BOT)['enabled'] ?? false); } public static function all(): array { $stored = Settings::get(self::KEY) ?? []; $mode = (string) ($stored['mode'] ?? self::GLOBAL); return [ 'mode' => in_array($mode, self::MODES, true) ? $mode : self::GLOBAL, 'alerts' => (bool) ($stored['alerts'] ?? true), 'billing' => (bool) ($stored['billing'] ?? true), 'user_install' => (bool) ($stored['user_install'] ?? true), 'eggs' => array_values(array_filter(array_map('strval', (array) ($stored['eggs'] ?? [])))), 'nodes' => array_values(array_filter(array_map('intval', (array) ($stored['nodes'] ?? [])))), 'console_images' => (bool) ($stored['console_images'] ?? true), 'disabled' => self::normaliseDisabled((array) ($stored['disabled'] ?? [])), 'slots' => max(1, min(self::MAX_SLOTS, (int) ($stored['slots'] ?? self::DEFAULT_SLOTS))), ]; } public static function save(array $values): void { $current = self::all(); $mode = (string) ($values['mode'] ?? $current['mode']); Settings::put(self::KEY, [ 'mode' => in_array($mode, self::MODES, true) ? $mode : self::GLOBAL, 'alerts' => (bool) ($values['alerts'] ?? false), 'billing' => (bool) ($values['billing'] ?? false), 'user_install' => (bool) ($values['user_install'] ?? false), 'eggs' => Egg::query()->whereIn('uuid', array_map('strval', (array) ($values['eggs'] ?? [])))->pluck('uuid')->values()->all(), 'nodes' => Node::query()->whereIn('id', array_map('intval', (array) ($values['nodes'] ?? [])))->pluck('id')->map(fn ($id) => (int) $id)->values()->all(), 'console_images' => (bool) ($values['console_images'] ?? $current['console_images']), 'disabled' => self::normaliseDisabled((array) ($values['disabled'] ?? $current['disabled'])), 'slots' => max(1, min(self::MAX_SLOTS, (int) ($values['slots'] ?? $current['slots']))), ]); } public static function disabledCommands(): array { return self::all()['disabled']; } public static function consoleImagesAllowed(): bool { return self::all()['console_images']; } public static function slots(): int { return self::all()['slots']; } public static function workerCapacity(): ?array { try { $pool = function_exists('fpm_get_status') ? (string) (@fpm_get_status()['pool'] ?? 'www') : 'www'; $version = PHP_MAJOR_VERSION . '.' . PHP_MINOR_VERSION; $files = array_merge( glob("/etc/php/{$version}/fpm/pool.d/*.conf") ?: [], glob('/etc/php-fpm.d/*.conf') ?: [], glob('/usr/local/etc/php-fpm.d/*.conf') ?: [], ); foreach ($files as $file) { $section = null; foreach (@file($file, FILE_IGNORE_NEW_LINES) ?: [] as $line) { $line = trim($line); if (preg_match('/^\[(.+)\]$/', $line, $match) === 1) { $section = $match[1]; } elseif ($section === $pool && preg_match('/^pm\.max_children\s*=\s*(\d+)/', $line, $match) === 1) { $workers = (int) $match[1]; return ['workers' => $workers, 'recommended' => max(2, intdiv($workers, 3))]; } } } } catch (Throwable) { } return null; } private static function normaliseDisabled(array $names): array { return array_values(array_intersect( array_diff(array_keys(BotSettings::CATALOGUE), BotSettings::ALWAYS_ON), array_map('strval', $names), )); } public static function scope(): array { $settings = self::all(); return ['eggs' => $settings['eggs'], 'nodes' => $settings['nodes']]; } public static function covers(?string $eggUuid, ?int $nodeId): bool { $scope = self::scope(); if ($scope['eggs'] !== [] && ($eggUuid === null || !in_array($eggUuid, $scope['eggs'], true))) { return false; } return $scope['nodes'] === [] || ($nodeId !== null && in_array($nodeId, $scope['nodes'], true)); } public static function coversServer(Server $server): bool { return self::covers($server->egg?->uuid, (int) $server->node_id); } public static function mode(): string { return self::all()['mode']; } public static function personal(): bool { return self::mode() === self::PERSONAL; } public static function alertsEnabled(): bool { return self::all()['alerts']; } public static function billingEnabled(): bool { return self::all()['billing'] && Billing::configured(); } public static function globalBot(): ?DiscordBot { return DiscordBot::query()->whereNull('user_id')->first(); } public static function personalBot(int $userId): ?DiscordBot { return DiscordBot::query()->where('user_id', $userId)->first(); } public static function serves(DiscordBot $bot): bool { return $bot->isGlobal() ? !self::personal() : self::personal(); } public static function interactionsUrl(DiscordBot $bot): string { return self::panelUrl(route('dezerx.discordbot.interactions', $bot->uuid, false)); } public static function inviteUrl(DiscordBot $bot): string { return 'https://discord.com/oauth2/authorize?' . http_build_query([ 'client_id' => $bot->application_id, 'scope' => 'bot applications.commands', 'permissions' => (string) self::PERMISSIONS, 'integration_type' => 0, ]); } public static function userInstallUrl(DiscordBot $bot): string { return 'https://discord.com/oauth2/authorize?' . http_build_query([ 'client_id' => $bot->application_id, 'scope' => 'applications.commands', 'integration_type' => 1, ]); } public static function oauthRedirect(): string { return self::panelUrl(route('dezerx.discordbot.callback', [], false)); } public static function portalUrl(DiscordBot $bot): string { return 'https://discord.com/developers/applications/' . $bot->application_id . '/information'; } public static function accent(): int { try { $rgb = OgImage::palette()['accent'] ?? [71, 165, 231]; } catch (Throwable) { $rgb = [71, 165, 231]; } return (($rgb[0] & 255) << 16) | (($rgb[1] & 255) << 8) | ($rgb[2] & 255); } public static function panelName(): string { $name = trim((string) config('app.name', 'Pterodactyl')); return $name !== '' ? $name : 'Pterodactyl'; } public static function panelUrl(string $path = ''): string { return rtrim((string) config('app.url'), '/') . ($path === '' ? '' : '/' . ltrim($path, '/')); } public static function panelHost(): string { $host = parse_url((string) config('app.url'), PHP_URL_HOST); return is_string($host) && $host !== '' ? $host : self::panelName(); } public static function panelLogo(): ?string { try { $logo = Appearance::logo(); } catch (Throwable) { return null; } foreach ([$logo['mark'] ?? '', $logo['image'] ?? ''] as $candidate) { $candidate = trim((string) $candidate); if ($candidate !== '' && preg_match('/\.(png|jpe?g|webp|gif)(\?.*)?$/i', $candidate) === 1) { return Art::absolute($candidate); } } return null; } public static function banner(): ?string { try { if (!OgImage::available()) { return null; } return self::panelUrl(route('dezerx.og', ['stamp' => OgImage::stamp(), 'slug' => 'dashboard'], false)); } catch (Throwable) { return null; } } } 